Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchButton(text = {{trigger}}, onClick = {}, variant = MonarchButtonVariant.Secondary)
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.lg)
            .padding(MonarchTheme.spacing.space4),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    ) {
        Row(verticalAlignment = Alignment.Top) {
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
                MonarchText(text = {{trigger}}, style = MonarchTextStyle.Heading)
                MonarchText(text = {{description}}, color = MonarchTheme.colors.textMuted)
            }
            MonarchIconButton(label = "Close", onClick = {}) {
                MonarchIcon(SampleIcons.Close, contentDescription = null)
            }
        }
        MonarchTextField(
            value = "",
            onValueChange = {},
            placeholder = "Filter shortcuts",
            leadingIcon = { MonarchIcon(SampleIcons.Search, contentDescription = null) },
        )
        sections.forEach { (group, items) ->
            if (group != null) {
                MonarchText(text = group.uppercase(), style = MonarchTextStyle.Label, color = MonarchTheme.colors.textMuted)
            }
            items.forEachIndexed { index, shortcut ->
                if (index > 0) MonarchDivider(variant = MonarchDividerVariant.Subtle)
                Row(
                    modifier = Modifier.fillMaxWidth().padding(vertical = MonarchTheme.spacing.space1),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                ) {
                    MonarchText(text = shortcut.label, modifier = Modifier.weight(1f))
                    shortcut.keys.forEachIndexed { alternative, chord ->
                        if (alternative > 0) MonarchText(text = "or", color = MonarchTheme.colors.textMuted)
                        chord.forEachIndexed { step, key ->
                            if (step > 0 && shortcut.sequence) MonarchText(text = "then", color = MonarchTheme.colors.textMuted)
                            MonarchText(
                                text = key,
                                modifier = Modifier
                                    .border(1.dp, MonarchTheme.colors.borderDefault, MonarchTheme.shapes.sm)
                                    .padding(horizontal = MonarchTheme.spacing.space2, vertical = MonarchTheme.spacing.space1),
                                style = MonarchTextStyle.Caption,
                            )
                        }
                    }
                }
            }
        }
    }
}

